import{_ as p,H as o,f as l,i}from"./chunks/framework.BH2BK_3i.js";const n=JSON.parse('{"title":"旅程再启｜SQL Copilot：AI时代下的SQL查询与优化","description":"","frontmatter":{},"headers":[],"relativePath":"SQL必知必会/旅程再启｜SQLCopilot：AI时代下的SQL查询与优化.md","filePath":"SQL必知必会/旅程再启｜SQLCopilot：AI时代下的SQL查询与优化.md","lastUpdated":1779816304000}'),e={name:"SQL必知必会/旅程再启｜SQLCopilot：AI时代下的SQL查询与优化.md"};function S(_,t,a,L,Q,r){return o(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="旅程再启-sql-copilot-ai时代下的sql查询与优化" tabindex="-1">旅程再启｜SQL Copilot：AI时代下的SQL查询与优化 <a class="header-anchor" href="#旅程再启-sql-copilot-ai时代下的sql查询与优化" aria-label="Permalink to &quot;旅程再启｜SQL Copilot：AI时代下的SQL查询与优化&quot;">​</a></h1><p>你好，我是陈博士，好久不见！</p><p>在专栏结束了五年多以后，我决定对专栏进行一次迭代，分享一些新的认知。</p><p>在这段时间里，基于我线下培训项目的沉淀，我对 SQL 在实践方面有了一些新的行业积累，比如银行、保险、证券、新能源车企、快消等等，看看它们是如何应用 SQL 进行数据分析，从而更好地支持业务的。当然，这些相关经验也可以进行复制，为你所用。</p><p>值得一提的是，在大模型的加持下，用自然语言写 SQL 查询已经变成了一件非常简单的事情。提示工程、上下文学习、推理增强、大模型调优等等都可以让 LLM 生成高质量的 SQL。</p><p>所以，在接下来的加餐中，我将给你讲述 AI 时代下的 SQL 查询技巧，同时结合不同场景下的 SQL 查询需求。当然通过这些场景示例，你也可以看到 Text to SQL 的撰写能力。</p><p><strong>目前拟定增加的话题如下：</strong></p><ol><li><p>Text to SQL：自然语言写SQL查询</p></li><li><p>SQL实战：银行场景的数据查询与优化</p></li><li><p>SQL实战：保险场景的数据查询与优化</p></li><li><p>SQL实战：证券场景的数据查询与优化</p></li><li><p>SQL实战：新能源车企的数据查询与优化</p></li><li><p>SQL实战：快消场景的数据查询与优化</p></li></ol><p>如果你有更多想要了解的内容，也欢迎在留言区写下你的问题，我们共同探讨！加更的部分，每周二和周四0点更新，敬请期待。</p>',9)])])}const c=p(e,[["render",S]]);export{n as __pageData,c as default};
